  },
  log() { return st.log; },
  coinDefs() { return coins.defs.map((d, i) => ({ s: d.s, lat: d.lat, taken: coins.collected[i] === 1 })); },
  /** QA: on-screen centre (px) and diameter (px) of every untaken coin in front of the camera */
  coinScreen() {
